var map = data.incidentLocation;
var markers = (map && map.features ? map.features : []).filter(function (feature) {
  return feature.type === 'marker';
});

var isInBC = function (marker) {
  var lat = marker.coordinates.lat;
  var lng = marker.coordinates.lng;
  return lat >= 48.2513 && lat <= 60 && lng >= -139.0596 && lng <= -114.0337;
};

show = !markers.every(isInBC);

validate.custom:
// Blocks submission when a map marker is outside BC. This field is hidden with the CSS class d-none
// because the map component has no Custom Validation of its own, and CHEFS skips validation on
// components hidden with the "Hidden" setting. The visible message is the HTML Element under the map,
// and its show/hide conditional uses the same BC bounds.

var map = data.incidentLocation;
var markers = (map && map.features ? map.features : []).filter(function (feature) {
  return feature.type === 'marker';
});

var isInBC = function (marker) {
  var lat = marker.coordinates.lat;
  var lng = marker.coordinates.lng;
  return lat >= 48.2513 && lat <= 60 && lng >= -139.0596 && lng <= -114.0337;
};

valid = markers.every(isInBC) ? true : 'The location must be within British Columbia';

components.customConditional:
// Same limits as the Custom Validation on the hidden "attachmentsLimitCheck" field.
var MAX_FILES = 5;
var MAX_FILE_BYTES = 21 * 1024 * 1024;
var MAX_TOTAL_BYTES = 50 * 1024 * 1024;

var files = data.simplefile || [];
var totalBytes = files.reduce(function (total, file) {
  return total + (file.size || 0);
}, 0);
var isFileTooLarge = files.some(function (file) {
  return (file.size || 0) > MAX_FILE_BYTES;
});

show = files.length > MAX_FILES || isFileTooLarge || totalBytes > MAX_TOTAL_BYTES;

