components.calculateValue:
// The label of the selected violation type, which NatSuite adds to the call details.
var field = Object.keys(data).find(function (key) {
  return /^violation_type_\d+$/.test(key) && data[key];
});
var radios = field && utils.getComponent(form.components, field);
var selected = radios && radios.values.find(function (option) {
  return option.value === data[field];
});

value = selected ? selected.label : '';
